#!/usr/bin/env python3
"""Report completed three-method planning without changing the frozen simulation."""
from __future__ import annotations

import importlib
import json

import numpy as np
import pandas as pd
from scipy.stats import beta

import wrr_r3_common as C

J = importlib.import_module("405_wrr_three_method_joint_power")


def main():
    settings = json.loads(J.CONFIG.read_text())
    decision = json.loads((J.OUT / "decision_all.json").read_text())
    if not decision["complete_prespecified_run"] or decision["completed_paired_head_refits"] != 3000:
        raise RuntimeError("Prespecified complete simulation has not finished")
    frame = pd.read_parquet(J.OUT / "procedures_all.parquet")
    summary = pd.read_csv(J.OUT / "power_all.csv")
    expected_cells = len(settings["simulated_training_groups"]) * len(settings["simulated_calibration_groups"]) * len(settings["simulated_test_groups"]) * len(settings["calibration_policies"])
    if len(summary) != expected_cells or not summary.repetitions.eq(settings["repetitions_per_training_size"]).all():
        raise RuntimeError("Missing budget cells or complete procedure repetitions")
    if not frame.true_joint_success.le(frame.joint_pass).all() or not frame.true_joint_success.le(frame.population_target_met).all():
        raise RuntimeError("Joint success does not include its population target")
    # These are grid-adjusted Monte Carlo intervals, not inferential bounds on
    # a new river population. Preserve the original pointwise CSV unchanged.
    successes = np.rint(summary.true_joint_power * summary.repetitions).astype(int)
    level = .025 / expected_cells
    summary["grid_MC_lower"] = [float(beta.ppf(level, k, n - k + 1)) if k else 0. for k, n in zip(successes, summary.repetitions)]
    summary["grid_MC_upper"] = [float(beta.ppf(1 - level, k + 1, n - k)) if k < n else 1. for k, n in zip(successes, summary.repetitions)]
    summary.to_csv(J.OUT / "power_with_grid_MC.csv", index=False)
    compact = summary.groupby(["training_groups", "policy"]).agg(
        budget_cells=("repetitions", "size"), repetitions_per_cell=("repetitions", "first"),
        maximum_joint_successes=("true_joint_power", lambda values: int(round(values.max() * settings["repetitions_per_training_size"]))),
        maximum_population_target_rate=("population_target_fraction", "max"),
        maximum_pointwise_MC_upper=("mc_upper", "max"), maximum_grid_MC_upper=("grid_MC_upper", "max")).reset_index()
    compact.to_csv(J.OUT / "compact_summary.csv", index=False)
    display = compact[["training_groups", "policy", "budget_cells", "maximum_joint_successes", "maximum_population_target_rate", "maximum_pointwise_MC_upper"]].copy()
    display["maximum_joint_successes"] = display.maximum_joint_successes.map(lambda k: f"{k}/1000")
    display["policy"] = display.policy.replace({"formal": "Formal", "empirical_sensitivity": "Empirical sensitivity"})
    display = display.rename(columns={"training_groups": "Train G", "policy": "Calibration", "budget_cells": "Cells", "maximum_joint_successes": "Max hits/cell", "maximum_population_target_rate": "Max target fraction", "maximum_pointwise_MC_upper": "MC upper"})
    writer = C.load_script("three_method_table_writer", C.ROOT / "scripts/383_wrr_followup_evidence.py")
    caption = ("Three-method, two-reference joint planning for the developed neural H30 point. Each training-size/policy row summarizes 72 calibration/evaluation budget cells, with 1,000 complete score-head refits, recalibrations and evaluations per cell. The reconstruction law remains frozen as specified for F2. Window boosting must exceed both native-CDF and matched direct boosting by five retention points while all three satisfy risk evidence with positive admission. The target fraction uses the finite role-specific simulation population, whereas hits additionally require evaluation bounds. MC upper is the largest pointwise 95-percent binomial Monte Carlo upper bound; the separate 432-cell-adjusted upper bound is 0.0097 when all hits are zero. Simulated group counts are not newly observed groups. The empirical calibration is a sensitivity only. Actual old development/calibration/test supports are 11/9/7 components; no new-target recruitment size or independent confirmation follows.")
    paper = C.ROOT / "paper/wrr"
    (paper / "si_r8_tables.tex").write_text("% Generated by script 407 from the completed script-405 run.\n" + writer.table(display, caption, "three_method_joint_power"))
    upper = summary.mc_upper.max()
    grid_upper = summary.grid_MC_upper.max()
    text = ("A separate completed planning experiment now implements the neural-point candidate and both direct references, rather than reusing the original paired plan. The old-only selected air32 probability law and 32 draws remain fixed; both matched boosting heads are refitted on resampled development components in each repetition. All methods share calibration compositions and paired evaluation groups, and score thresholds use training-fixed candidate families. The three formal calibrations and three evaluation-risk tests each receive $\\alpha=0.005$; each of the two gain tests receives 0.01. Their familywise allocation is 0.05. Empirical calibration at its original 0.05 level is reported only as a sensitivity, with the same independent evaluation-risk and paired-gain requirements.\n\n"
            "Training budgets 60/120/240, calibration budgets 16/60/120/240/480/960/1920/3840 and evaluation budgets 10/60/120/240/480/960/1920/3840/7680 give 432 cells across the two calibration policies. Three thousand complete paired-head refits produce zero joint successes in each cell's 1,000 repetitions (Table~\\ref{tab:three_method_joint_power}). "
            f"The pointwise 95\\% Monte Carlo upper bound is {100*upper:.2f}\\%; the simultaneous 432-cell upper bound is {100*grid_upper:.2f}\\%. These quantify finite simulation uncertainty, not target-population risk. The actual role supports are only 11/9/7 already opened Swiss components. Independent draws from those finite laws cannot generate new climate, process or regional-event types. No tested budget supports the 80\\% joint-power target, and no new-population recruitment size is recommended. New Australian reference qualification has not opened target prediction errors and does not turn these simulated budgets into acquired independent units.\n")
    (paper / "r8_three_method_planning.tex").write_text(text)
    C.write_json(J.OUT / "evidence_summary.json", {
        "complete_paired_head_refits": 3000, "budget_cells": expected_cells,
        "joint_hits_per_cell": sorted(set(successes.tolist())),
        "maximum_pointwise_MC_upper": float(upper), "maximum_grid_MC_upper": float(grid_upper),
        "MC_bounds_describe_the_simulation_not_new_river_evidence": True,
        "new_population_recruitment_N": None, "new_independent_confirmation_completed": False})
    print(f"[407] {expected_cells} complete cells reported; no new-target confirmation or recommended N", flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
